struct Point {
  int x, y;
  bool operator==(const Point&)
      const = default;
};

int main() {
  std::unordered_map<Point, std::string>
      labels;
  labels[{1, 2}] = "a";
  std::cout << labels.size() << '\n';
}

template <>
struct std::hash<Point> {
  std::size_t operator()(const Point& p)
      const noexcept {
    std::size_t s = std::hash<int>{}(p.x);
    s ^= std::hash<int>{}(p.y) + 0x9e3779b9
         + (s << 6) + (s >> 2);
    return s;
  }
};  // now labels.size() prints 1

std::unordered_map<int, std::string> m{
    {1, "one"}};
std::string& ref = m[1];
std::string* ptr = &m[1];
auto it = m.find(1);

m.reserve(1000);  // forces a rehash

std::cout << ref << '\n';         // A
std::cout << *ptr << '\n';        // B
std::cout << it->second << '\n';  // C

std::unordered_map<int, int> m;
for (int i = 0; i < 5; ++i) m[i * 10] = i;

for (const auto& [k, v] : m)
  std::cout << k << ' ';
std::cout << '\n';

m.rehash(1000);
for (const auto& [k, v] : m)
  std::cout << k << ' ';

std::vector<int> keys;
for (const auto& [k, v] : m)
  keys.push_back(k);
std::sort(keys.begin(), keys.end());
for (int k : keys)
  std::cout << k << ' ';
